"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["5076"],{1753(e,t,n){n.r(t),n.d(t,{metadata:()=>r,default:()=>h,frontMatter:()=>a,contentTitle:()=>s,toc:()=>c,assets:()=>d});var r=JSON.parse('{"id":"reference/orders","title":"Orders","description":"connectivity \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/orders.md","sourceDirName":"reference","slug":"/reference/orders","permalink":"/personal-av-docs/docs/reference/orders","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/orders.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"Orders","sidebar_label":"Orders","sidebar_position":99,"edition":"connectivity","source":"https://doc.airvantage.net/connectivity/reference/orders","format":"md"}}'),o=n(4848),i=n(8453);let a={title:"Orders",sidebar_label:"Orders",sidebar_position:99,edition:"connectivity",source:"https://doc.airvantage.net/connectivity/reference/orders",format:"md"},s,d={},c=[];function l(e){let t={a:"a",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsxs)(t.p,{children:[":::note Edition\n",(0,o.jsx)(t.strong,{children:"connectivity"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,o.jsx)(t.a,{href:"https://doc.airvantage.net/connectivity/reference/orders",children:"Original page"}),".\n:::"]}),"\n",(0,o.jsxs)(t.p,{children:["Orders\nBilling\nAdministration\nSubaccounts\nConnectivity Management\nDashboard\nMonitor\nConfigure\nAPI, Connectors & Other Services\nWeb Services API\nCloud Connectors\nCloud Connectors Format\nUSSD Gateway\nMore\nProduct page\nSearching...\nMatching results\nOrders\nThis section explains how you can order new SIMs and track the status of your order.\nInitializing Table Of Contents...\nOrdering new SIMs\nOrdering new SIMs can be done very easily by connecting to your account at\n",(0,o.jsx)(t.a,{href:"https://eu.airvantage.net/accounts/",children:"https://eu.airvantage.net/accounts/"}),"\nYou can submit an order in two ways:\nBy using directly the order widget in the start page dashboard\nBy selecting\nOrders\nin the top banner activities and then click on the Order button\nYou will be prompted for the following inputs:\nAs part of the product reference, select in the drop down the product you want to order. For ease of use, the selection is limited to the products that have been qualified for your account.\nProvide the quantity that you need. Be aware that if you choose a quantity lower than the Minimum Order Quantity, the order may be rejected or administrative fees may apply.\nSelect a delivery address. By default, you can deliver the SIM cards to the Billing Contact provided as part of the contract. If you want to add a new delivery contact, you do this easily by clicking on the (+) field at the right of the drop down, or by navigating to\nAdministration > Delivery contact\nmenu.\nIn the Advanced section, you can find\noptional\nfields that you can use for your own tracking purposes, or that propose additional functionalities:\nCustom ID: for adding the reference of the PO in your own system. This Custom ID will be shown in the orders report aside of invoice to enable easy order tracking.\nDescription: which is visible from your users only (not transmitted as part of the order) and can be used for any internal notes about the order.\nSchedule order for: which can permit to schedule your order in the future and therefore plan your next orders. To be noted that the date provided is an order date, not an expected delivery date. If you want to receive your order before a given date, you need to allow sufficient time for the order to be treated and shipped.\nPre-activation offer: for security purpose, we are shipping our SIMs cold, meaning not activated to prevent any misuse in case of lost order. If you need to activate the SIMs as part of your factory process, you can either use the activation APIs (preferred option) or use this pre-activation option. With pre-activation, simply choose the offer on which you want the SIMs to be activated and as soon as the SIMs will be provisioned in your account, an activation operation will be launched automatically. Please be aware that the later option may expose you to fraudulent consumption in case the order is lost; reason why we are advising to use APIs as a first choice.\nWhen you are ready, click on\nOrder\n.\nFollowing-up a submitted SIM order\nOnce the order has been submitted, you can follow up its status.\nA SIM order can be in the following statuses:\nScheduled\nUpon submission of an order with an order date in the future, the order is created in Scheduled state. It means Sierra will not take your order into account and therefore will not accept it until the order date has elapsed. While the order is in \u2018Scheduled\u2019 state, you may cancel it if necessary.\nPending\nUpon submission, the order is created in Pending state. It means Sierra has not yet been taken your order into account. In case you would like to cancel a submitted order, this can only be done in case the order is still \u2018Pending\u2019.\nAccepted\nOnce Sierra accepts the order, it is switched into Accepted state. An email notification is also sent to the company administrators including the expected shipment date if information is available. Once accepted an order cannot be cancelled any more.\nAnother email notification will also be sent in case of change to the expected shipment date. From the order section in AirVantage  you can find the expected shipment date information under the state of the order.\nCancelled\nYou have the capability to cancel an order that has been placed earlier, in case of error in the order submission. Cancelling an order is only possible for orders in state Pending. Once accepted an order cannot be cancelled any more.\nRejected\nSierra reserves the right to reject an order. In case of rejection, you will receive an e-mail explaining the rejection cause.\nShipped\nUpon shipment, the order state will switch to Shipped. An email notification is also sent to the company administrators and delivery contact to advise them of shipment. From the order section in AirVantage  you can find the tracking information for easy tracking of the parcel. The SIMs are shipped unactivated and cannot be used unless you activate them.\nDelivered\nYou can mark the order as delivered by going to the\nOrders Activity\nand clicking in the Action column of the order just received. A \u2018Delivered\u2019 order will be considered as a past order, and will not be displayed if you use the \u2018Current\u2019 filter in the orders grid.\nBy clicking on one specific order, you can view its details:\nFrom the details you can see all the information related to your order, including the internal description that has been provided during ordering. Depending on the state of the order, you will be able to:\nsee the expected shipment date (for orders in state Accepted)\nsee the tracking url that will enable you to track the shipment directly with the delivery supplier (for orders in state Shipped)\ndownload the list of ICCIDs attributed to this specific order. Using the \u2018Manage my Connectivity\u2019 link, you can easily switch to the connectivity management activity to activate all the SIMs you have just received (they will be filtered using the orderID label).\nCancelling a submitted SIM order\nYou have the capability to cancel an order that has been placed earlier, in case of error in the order submission. To cancel an order, drill down to the order details and press the cancel button on the top right hand corner.\nPlease note that cancelling an order is only possible for orders in state Pending or Scheduled. Once accepted an order cannot be cancelled any more.\nAcknowledging the delivery of a SIM order\nOnce received, we invite you to mark the order as delivered. A \u2018Delivered\u2019 order will be considered as a past order, and will not be displayed if you use the \u2018Current\u2019 filter in the orders grid. Acknowledging the delivery of a shipped  order is however not mandatory, and will not prevent from activating the SIMs.\nOrders List\nYou can view all your order history by selecting\nOrders\nin the top banner activities.\nFilters on the top left hand corner permit to restrict the view to only:\nthe \u2018current\u2019 orders that may require attention (pending, accepted or shipped),\nthe \u2018past\u2019 orders (that have been cancelled, rejected or marked as delivered)\nor the orders that are \u2018scheduled\u2019 for a future date.\nFor convenience, you also have a summary of the 5 most recent orders from the \u2018Current\u2019 section directly displayed in the start page dashboard.\nHow-Tos\nThis section provides you with helpful procedures for common tasks.\nHow to activate the SIMs upon order reception?\nHow to order new SIMs?\nHow to plan my orders for the year?"]})]})}function h(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(l,{...e})}):l(e)}},8453(e,t,n){n.d(t,{R:()=>a,x:()=>s});var r=n(6540);let o={},i=r.createContext(o);function a(e){let t=r.useContext(i);return r.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:a(e.components),r.createElement(i.Provider,{value:t},e.children)}}}]);